source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    divider = 2
    horizontal = [r for r in range(h) if all(v == divider for v in grid[r])]
    vertical = [c for c in range(w) if all(grid[r][c] == divider for r in range(h))]
    if horizontal:
        axis, pos = 'h', horizontal[0]
    elif vertical:
        axis, pos = 'v', vertical[0]
    else:
        return out
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != divider]
    if not cells:
        return out
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    if axis == 'h':
        if r0 > pos:
            dr = pos + 1 - r0
        else:
            dr = pos - 1 - r1
        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            out[r + dr][c] = grid[r][c]
        stripe = (r1 + dr + 1) if r0 > pos else (r0 + dr - 1)
        if 0 <= stripe < h:
            out[stripe] = [8] * w
    else:
        if c0 > pos:
            dc = pos + 1 - c0
        else:
            dc = pos - 1 - c1
        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            out[r][c + dc] = grid[r][c]
        stripe = (c1 + dc + 1) if c0 > pos else (c0 + dc - 1)
        if 0 <= stripe < w:
            for r in range(h):
                out[r][stripe] = 8
    return out
'''
